const STAT_ICONS = [StatIconSmiley, StatIconPeople, StatIconDocumentTeam, StatIconAward];

export default function FAQs10({ content }) {
  const faqsBlock = content?.faqs ?? {};
  const faqItems = Array.isArray(faqsBlock)
    ? faqsBlock
    : (faqsBlock?.items ?? faqsBlock?.value ?? []);

  const faqTitle = faqsBlock?.title ?? "";
  const rightIntro =
    (typeof faqsBlock.right_intro === "string" && faqsBlock.right_intro) ||
    (typeof faqsBlock.description === "string" && faqsBlock.description) ||
    "";

  const statsRaw = faqsBlock?.stats;
  const stats = Array.isArray(statsRaw) ? statsRaw : [];

  const defaultOpenRaw = Array.isArray(faqsBlock)
    ? null
    : faqsBlock?.default_open_index;
  const initialOpen =
    typeof defaultOpenRaw === "number" &&
      defaultOpenRaw >= 0 &&
      defaultOpenRaw < faqItems.length
      ? defaultOpenRaw
      : null;

  const [activeIndex, setActiveIndex] = useState(initialOpen);

  if (!Array.isArray(faqItems) || faqItems.length === 0) return null;

  const showRightColumn = Boolean(rightIntro) || stats.length > 0;

  return (
    <FullContainer className="bg-white py-10 md:py-14 lg:py-16" id="faqs">
      <Container className="px-4 sm:px-6 lg:px-8">
        <div
          className={`mx-auto grid max-w-7xl gap-10 lg:grid-cols-2 lg:items-start lg:gap-12 xl:gap-16 ${poppins.className}`}
        >
          <div className="min-w-0 text-left">
            {faqTitle ? (
              <>
                <h2
                  className={`max-w-[485px] text-[44px] font-semibold leading-[1.15] text-[#232228] ${montserrat.className}`}
                >
                  {faqTitle}
                </h2>
                <div
                  className="mb-[30px] mt-[30px] max-w-[537px] border-b border-[#232228]"
                  aria-hidden
                />
              </>
            ) : null}

            <div className="flex w-full max-w-[537px] flex-col gap-[12px]">
              {faqItems.map((faq, index) => {
                const isOpen = activeIndex === index;
                const q = faq?.question ?? faq?.q ?? "";
                const a = faq?.answer ?? faq?.a ?? "";
                return (
                  <div
                  key={faq?.id ?? index}
                  className={
                    isOpen
                      ? "w-full max-w-[537px]"
                      : "h-[50px] w-full max-w-[537px] overflow-hidden rounded-[4px] border border-[#232228]"
                  }
                >
                    <button
                      type="button"
                      id={`faq-btn-${index}`}
                      className={`flex w-full items-center justify-between text-left ${
                        isOpen
                          ? "border-b border-[#232228] px-0 pb-[14px]"
                          : "h-[50px] px-[14px]"
                      }`}
                      onClick={() =>
                        setActiveIndex(activeIndex === index ? null : index)
                      }
                      aria-expanded={isOpen}
                      aria-controls={`faq-content-${index}`}
                    >
                      <span className="min-w-0 pr-3 text-[18px] font-semibold leading-snug text-[#232228]">
                        {q}
                      </span>
                      <span className="inline-flex h-[22px] w-[22px] shrink-0 items-center justify-center rounded-full border border-[#232228] text-[#232228]">
                        {isOpen ? (
                          <Minus size={14} strokeWidth={2.5} />
                        ) : (
                          <Plus size={14} strokeWidth={2.5} />
                        )}
                      </span>
                    </button>
                    {isOpen && a ? (
                      <div
                        id={`faq-content-${index}`}
                        role="region"
                        aria-labelledby={`faq-btn-${index}`}
                        className="pt-[14px]"
                      >
                        <p className="max-w-[500px] text-[15px] leading-loose text-[#6B7280]">
                          {a}
                        </p>
                      </div>
                    ) : null}
                  </div>
                );
              })}
            </div>
          </div>
          {showRightColumn ? (
            <div
              className={`min-w-0 ${faqTitle ? "pt-15 lg:pt-29 xl:pt-31" : ""}`}
            >
              {rightIntro ? (
                <p className="mb-10 text-left text-sm leading-relaxed text-neutral-700 md:mb-10 md:text-base">
                  {rightIntro}
                </p>
              ) : null}

              {stats.length > 0 ? (
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  {stats.map((row, i) => {
                    const Icon = STAT_ICONS[i] ?? STAT_ICONS[0];
                    const value = row?.value ?? "";
                    const label = row?.label ?? "";
                    return (
                      <div
                        key={row?.id ?? i}
                        className="flex items-center gap-4 rounded-2xl px-5 py-5 text-white shadow-md md:px-6 md:py-6"
                        style={{ backgroundColor: STAT_CARD_BG }}
                      >
                        <Icon className="h-12 w-12 shrink-0 md:h-14 md:w-14" />
                        <div className="min-w-0">
                          <p className="text-2xl font-bold leading-none tracking-tight md:text-3xl">
                            {value}
                          </p>
                          {label ? (
                            <p className="mt-2 text-sm font-medium leading-snug text-white/95 md:text-base">
                              {label}
                            </p>
                          ) : null}
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : null}
            </div>
          ) : null}
        </div>
      </Container>
    </FullContainer>
  );
}
